Definition g_tls_index : Z := 0x10b890.
Definition g_dtv_ptr : Z := 0x64cf40.            (* [comment removed for export] *)
Definition g_dtv : Z := 0x64cf68.
Definition g_dtv1 : Z := 0x64cf70.            (* [comment removed for export] *)
Definition dtv1_val : Z := 0x64d748.         (* [comment removed for export] *)
Definition g_real_tls_get_addr : Z := 0x10c970.
